Для безопасного чтения JSON-файла в Rust используется крейт `serde_json` в сочетании с `std::fs`. Ключевой принцип — не вызывать `unwrap()` и `expect()` в местах, где ошибка возможна, а возвращать `Result` и обрабатывать все варианты отказа: отсутствие файла, ошибку прав доступа, некорректный JSON, несоответствие схеме. Ниже приведён полный пример с собственной ошибкой, реализующей `std::error::Error`, и функцией, возвращающей `Result`.

```rust
use std::fs;
use std::path::Path;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Config {
    name: String,
    port: u16,
    enabled: bool,
}

#[derive(Debug)]
enum ConfigError {
    Io(std::io::Error),
    Parse(serde_json::Error),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "ошибка ввода-вывода: {e}"),
            ConfigError::Parse(e) => write!(f, "ошибка разбора JSON: {e}"),
        }
    }
}

impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ConfigError::Io(e) => Some(e),
            ConfigError::Parse(e) => Some(e),
        }
    }
}

impl From<std::io::Error> for ConfigError {
    fn from(e: std::io::Error) -> Self {
        ConfigError::Io(e)
    }
}

impl From<serde_json::Error> for ConfigError {
    fn from(e: serde_json::Error) -> Self {
        ConfigError::Parse(e)
    }
}

fn read_config(path: &Path) -> Result<Config, ConfigError> {
    let content = fs::read_to_string(path)?;
    let config: Config = serde_json::from_str(&content)?;
    Ok(config)
}

fn main() {
    let path = Path::new("config.json");
    match read_config(path) {
        Ok(cfg) => println!("Загружено: {:?}", cfg),
        Err(e) => {
            eprintln!("Не удалось прочитать конфигурацию: {e}");
            if let Some(src) = std::error::Error::source(&e) {
                eprintln!("Причина: {src}");
            }
            std::process::exit(1);
        }
    }
}
```

