use serde_json::Error as JsonError;

#[derive(Debug, Deserialize)]
struct Config {
    name: String,
    port: u16,
}

// Пробрасывание ошибки через ? с добавлением контекста
fn parse_config(raw: &str) -> Result<Config, String> {
    serde_json::from_str::<Config>(raw)
        .map_err(|e| format!("не удалось разобрать конфиг: {e} (строка {}, столбец {})", e.line(), e.column()))
}

// Детальная классификация ошибки
fn describe_error(err: &JsonError) -> &'static str {
    if err.is_io() {
        "ошибка ввода-вывода"
    } else if err.is_syntax() {
        "синтаксическая ошибка JSON"
    } else if err.is_data() {
        "данные не соответствуют схеме"
    } else if err.is_eof() {
        "неожиданный конец ввода"
    } else {
        "неизвестная ошибка"
    }
}

fn main() {
    let good = r#"{"name":"app","port":8080}"#;
    let bad_syntax = r#"{"name":"app",}"#;
    let bad_data = r#"{"name":"app","port":"not-a-number"}"#;

    match parse_config(good) {
        Ok(cfg) => println!("конфиг: {cfg:?}"),
        Err(msg) => eprintln!("{msg}"),
    }

    for raw in [bad_syntax, bad_data] {
        match serde_json::from_str::<Config>(raw) {
            Ok(cfg) => println!("конфиг: {cfg:?}"),
            Err(e) => eprintln!("{}: {e}", describe_error(&e)),
        }
    }

    // Комбинаторы: значение по умолчанию и мягкая деградация
    let cfg = serde_json::from_str::<Config>(bad_data)
        .unwrap_or_else(|_| Config { name: "default".into(), port: 80 });
    println!("fallback: {cfg:?}");
}
```

