use std::io;
use std::path::Path;

// Проверка через try_exists с различением причин
fn check_exists(path: &Path) -> Result<bool, io::Error> {
    path.try_exists()
}

// Рекомендуемый подход: открыть и обработать ошибку открытия
fn read_file(path: &Path) -> Result<String, String> {
    match fs::read_to_string(path) {
        Ok(content) => Ok(content),
        Err(e) if e.kind() == io::ErrorKind::NotFound => {
            Err(format!("файл не найден: {}", path.display()))
        }
        Err(e) if e.kind() == io::ErrorKind::PermissionDenied => {
            Err(format!("нет прав на чтение: {}", path.display()))
        }
        Err(e) => Err(format!("ошибка чтения {}: {e}", path.display())),
    }
}

fn main() {
    let path = Path::new("data.txt");

    // Вариант 1: явная проверка существования
    match check_exists(path) {
        Ok(true) => println!("файл существует"),
        Ok(false) => println!("файла нет"),
        Err(e) => eprintln!("не удалось проверить: {e}"),
    }

    // Дополнительно: убедиться, что это именно файл, а не каталог
    if path.is_file() {
        println!("это обычный файл");
    }

    // Вариант 2: сразу читать с обработкой ошибки
    match read_file(path) {
        Ok(content) => println!("прочитано {} байт", content.len()),
        Err(msg) => eprintln!("{msg}"),
    }
}
```

