fn read_number(path: &str) -> Result<i32, io::Error> {
    let content = fs::read_to_string(path)?; // при ошибке — ранний возврат
    let trimmed = content.trim();
    // parse возвращает ParseIntError, поэтому нужно преобразование
    let value: i32 = trimmed.parse().map_err(|e: ParseIntError| {
        io::Error::new(io::ErrorKind::InvalidData, e)
    })?;
    Ok(value)
}

// Пример 2: собственный тип ошибки с реализацией From
