    let content = fs::read_to_string(path)?; // io::Error -> AppError
    let value: i32 = content.trim().parse()?; // ParseIntError -> AppError
    Ok(value)
}

// Пример 3: ? с Option
fn first_char(s: &str) -> Option<char> {
    let c = s.chars().next()?; // None — ранний возврат None
    Some(c)
}

