use std::fs::{self, File};
use std::io::{self, Read};

// Способ 1: take — читаем не более limit байт
fn read_limited_take(path: &str, limit: u64) -> io::Result<Vec<u8>> {
    let file = File::open(path)?;
    let mut buf = Vec::new();
    file.take(limit).read_to_end(&mut buf)?;
    Ok(buf)
}

// Способ 2: строгая проверка размера до чтения
fn read_with_size_check(path: &str, limit: u64) -> io::Result<Vec<u8>> {
    let meta = fs::metadata(path)?;
